INSERT INTO vehicles (slug, title, make, model, year, price, mileage, fuel, transmission, body, description, status, recency_rank, source) VALUES ('2016-ford-ranger-3-2-wildtrak-4x4-6speed-manual', '2016 FORD RANGER 3.2 WILDTRAK 4X4 6SPEED MANUAL', 'Ford', 'Ranger 3.2 Wildtrak 4X4 6Speed Manual', 2016, 13991, 103453, 'Diesel', 'Automatic', 'Pickup', 'Just arrived...103,453 MILES ONLY+ SERVICE HISTORY+12 months MOT+ This 2016 Ford Ranger Wildtrak 3.2 TDCi 4WD offers exceptional capability, boasting a substantial 3500 kg towing weight. This robust four wheel drive pickup is powered by a capable 3.2 litre diesel engine, making it ready for demanding tasks. The Wildtrak derivative comes equipped with a useful gearshift indicator light to help optimise fuel efficiency, automatic headlights for convenience, and Bluetooth connectivity for audio streaming. For added comfort, the front seats are heated, and rear parking sensors provide assistance when manoeuvring. The Ford Ranger Wildtrak stands out with its thoughtful features designed to enhance your driving experience. The inclusion of heated seats and automatic headlights demonstrates a focus on driver comfort and ease of use, setting it apart from other vehicles in its class. Its four wheel drive system and powerful 3.2 litre diesel engine ensure it is well equipped for a variety of conditions and work requirements, further highlighting its superior performance and versatility. £13991', 'available', 23, 'vans');
